import os
import time
import logging

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field
from litellm import acompletion

app = FastAPI(title="LLM Gateway")

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("llm-gateway")

# Demonstration only.
# Use a secure credential store in production.
API_KEYS = {
    os.getenv("TENANT_A_KEY", "demo-key-a"): "tenant_a",
    os.getenv("TENANT_B_KEY", "demo-key-b"): "tenant_b",
}

ALLOWED_MODELS = {
    "openai/gpt-4.1-mini",
}

class ChatRequest(BaseModel):
    prompt: str = Field(min_length=1, max_length=10000)
    model: str = "openai/gpt-4.1-mini"

class ChatResponse(BaseModel):
    tenant_id: str
    model: str
    answer: str
    input_tokens: int | None = None
    output_tokens: int | None = None
    latency_ms: int

@app.post("/chat", response_model=ChatResponse)
async def chat(
    request: ChatRequest,
    authorization: str = Header(...)
):
    start_time = time.perf_counter()

    # 1. Authenticate client
    if not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=401,
            detail="Invalid authorization format"
        )

    api_key = authorization.removeprefix("Bearer ")
    tenant_id = API_KEYS.get(api_key)

    if not tenant_id:
        raise HTTPException(
            status_code=401,
            detail="Invalid API key"
        )

    # 2. Validate model
    if request.model not in ALLOWED_MODELS:
        raise HTTPException(
            status_code=403,
            detail="Model not allowed"
        )

    try:
        # 3. Call provider through LiteLLM
        response = await acompletion(
            model=request.model,
            messages=[
                {
                    "role": "user",
                    "content": request.prompt
                }
            ],
            timeout=30
        )

        answer = response.choices[0].message.content

        # 4. Collect usage
        usage = response.usage

        input_tokens = (
            usage.prompt_tokens if usage else None
        )

        output_tokens = (
            usage.completion_tokens if usage else None
        )

        latency_ms = int(
            (time.perf_counter() - start_time) * 1000
        )

        # 5. Structured operational logging
        logger.info(
            "llm_request_completed",
            extra={
                "tenant_id": tenant_id,
                "model": request.model,
                "input_tokens": input_tokens,
                "output_tokens": output_tokens,
                "latency_ms": latency_ms,
                "status": "success"
            }
        )

        return ChatResponse(
            tenant_id=tenant_id,
            model=request.model,
            answer=answer or "",
            input_tokens=input_tokens,
            output_tokens=output_tokens,
            latency_ms=latency_ms
        )

    except Exception:
        logger.exception(
            "llm_request_failed",
            extra={"tenant_id": tenant_id}
        )

        raise HTTPException(
            status_code=502,
            detail="LLM provider request failed"
        )

@app.get("/health/live")
async def liveness():
    return {"status": "alive"}

